You are implementing features for a Blazor Web App shipment tracker at `/tmp/sv-69d66fa2b31d4736abb3935b2f623552/ShipmentTracker/`. The project uses Interactive Auto, Global mode with Individual authentication.

Project structure:
- `ShipmentTracker/` - server project
- `ShipmentTracker.Client/` - client project (all interactive components go here)

The app tracks shipments for a logistics company. Requirements:
- Dispatchers view a list of shipments with status and destination
- Customers check their shipment status and estimated delivery
- Authentication with roles (Dispatcher, Customer)

## What to implement:

### 1. Shared Models in Client project

Create `ShipmentTracker.Client/Models/Shipment.cs`:
```csharp
namespace ShipmentTracker.Client.Models;

public class Shipment
{
    public int Id { get; set; }
    public string TrackingNumber { get; set; } = string.Empty;
    public string Origin { get; set; } = string.Empty;
    public string Destination { get; set; } = string.Empty;
    public ShipmentStatus Status { get; set; }
    public DateTime CreatedDate { get; set; }
    public DateTime? EstimatedDelivery { get; set; }
    public string CustomerEmail { get; set; } = string.Empty;
    public string Description { get; set; } = string.Empty;
}

public enum ShipmentStatus
{
    Pending,
    PickedUp,
    InTransit,
    OutForDelivery,
    Delivered,
    Exception
}
```

### 2. Service Interface in Client project

Create `ShipmentTracker.Client/Services/IShipmentService.cs`:
```csharp
namespace ShipmentTracker.Client.Services;

using ShipmentTracker.Client.Models;

public interface IShipmentService
{
    Task<List<Shipment>> GetAllShipmentsAsync();
    Task<List<Shipment>> GetShipmentsForCustomerAsync(string email);
    Task<Shipment?> GetShipmentByTrackingNumberAsync(string trackingNumber);
    Task<Shipment> CreateShipmentAsync(Shipment shipment);
    Task UpdateShipmentStatusAsync(int id, ShipmentStatus status);
}
```

### 3. Client-side implementation using HttpClient

Create `ShipmentTracker.Client/Services/ShipmentServiceClient.cs`:
```csharp
using System.Net.Http.Json;
using ShipmentTracker.Client.Models;

namespace ShipmentTracker.Client.Services;

public class ShipmentServiceClient(HttpClient httpClient) : IShipmentService
{
    public async Task<List<Shipment>> GetAllShipmentsAsync()
    {
        return await httpClient.GetFromJsonAsync<List<Shipment>>("api/shipments") ?? [];
    }

    public async Task<List<Shipment>> GetShipmentsForCustomerAsync(string email)
    {
        return await httpClient.GetFromJsonAsync<List<Shipment>>($"api/shipments/customer/{Uri.EscapeDataString(email)}") ?? [];
    }

    public async Task<Shipment?> GetShipmentByTrackingNumberAsync(string trackingNumber)
    {
        return await httpClient.GetFromJsonAsync<Shipment?>($"api/shipments/track/{Uri.EscapeDataString(trackingNumber)}");
    }

    public async Task<Shipment> CreateShipmentAsync(Shipment shipment)
    {
        var response = await httpClient.PostAsJsonAsync("api/shipments", shipment);
        response.EnsureSuccessStatusCode();
        return await response.Content.ReadFromJsonAsync<Shipment>() ?? shipment;
    }

    public async Task UpdateShipmentStatusAsync(int id, ShipmentStatus status)
    {
        var response = await httpClient.PutAsJsonAsync($"api/shipments/{id}/status", status);
        response.EnsureSuccessStatusCode();
    }
}
```

### 4. Server-side implementation

Create `ShipmentTracker/Services/ShipmentServiceServer.cs`:
```csharp
using Microsoft.EntityFrameworkCore;
using ShipmentTracker.Client.Models;
using ShipmentTracker.Client.Services;
using ShipmentTracker.Data;

namespace ShipmentTracker.Services;

public class ShipmentServiceServer(ApplicationDbContext db) : IShipmentService
{
    public async Task<List<Shipment>> GetAllShipmentsAsync()
    {
        return await db.Shipments.OrderByDescending(s => s.CreatedDate).ToListAsync();
    }

    public async Task<List<Shipment>> GetShipmentsForCustomerAsync(string email)
    {
        return await db.Shipments
            .Where(s => s.CustomerEmail == email)
            .OrderByDescending(s => s.CreatedDate)
            .ToListAsync();
    }

    public async Task<Shipment?> GetShipmentByTrackingNumberAsync(string trackingNumber)
    {
        return await db.Shipments.FirstOrDefaultAsync(s => s.TrackingNumber == trackingNumber);
    }

    public async Task<Shipment> CreateShipmentAsync(Shipment shipment)
    {
        shipment.CreatedDate = DateTime.UtcNow;
        shipment.TrackingNumber = GenerateTrackingNumber();
        db.Shipments.Add(shipment);
        await db.SaveChangesAsync();
        return shipment;
    }

    public async Task UpdateShipmentStatusAsync(int id, ShipmentStatus status)
    {
        var shipment = await db.Shipments.FindAsync(id);
        if (shipment is not null)
        {
            shipment.Status = status;
            await db.SaveChangesAsync();
        }
    }

    private static string GenerateTrackingNumber()
    {
        return $"SHP-{DateTime.UtcNow:yyyyMMdd}-{Random.Shared.Next(10000, 99999)}";
    }
}
```

### 5. Add DbSet to ApplicationDbContext

The file is at `ShipmentTracker/Data/ApplicationDbContext.cs`. Add:
```csharp
using ShipmentTracker.Client.Models;
```
And add a DbSet property:
```csharp
public DbSet<Shipment> Shipments => Set<Shipment>();
```

### 6. API Endpoints

Create `ShipmentTracker/Endpoints/ShipmentEndpoints.cs`:
```csharp
using Microsoft.EntityFrameworkCore;
using ShipmentTracker.Client.Models;
using ShipmentTracker.Data;

namespace ShipmentTracker.Endpoints;

public static class ShipmentEndpoints
{
    public static void MapShipmentEndpoints(this WebApplication app)
    {
        var group = app.MapGroup("api/shipments").RequireAuthorization();

        group.MapGet("", async (ApplicationDbContext db) =>
            await db.Shipments.OrderByDescending(s => s.CreatedDate).ToListAsync());

        group.MapGet("customer/{email}", async (string email, ApplicationDbContext db) =>
            await db.Shipments
                .Where(s => s.CustomerEmail == Uri.UnescapeDataString(email))
                .OrderByDescending(s => s.CreatedDate)
                .ToListAsync());

        group.MapGet("track/{trackingNumber}", async (string trackingNumber, ApplicationDbContext db) =>
            await db.Shipments.FirstOrDefaultAsync(s => s.TrackingNumber == Uri.UnescapeDataString(trackingNumber)));

        group.MapPost("", async (Shipment shipment, ApplicationDbContext db) =>
        {
            shipment.CreatedDate = DateTime.UtcNow;
            shipment.TrackingNumber = $"SHP-{DateTime.UtcNow:yyyyMMdd}-{Random.Shared.Next(10000, 99999)}";
            db.Shipments.Add(shipment);
            await db.SaveChangesAsync();
            return Results.Created($"api/shipments/track/{shipment.TrackingNumber}", shipment);
        });

        group.MapPut("{id}/status", async (int id, ShipmentStatus status, ApplicationDbContext db) =>
        {
            var shipment = await db.Shipments.FindAsync(id);
            if (shipment is null) return Results.NotFound();
            shipment.Status = status;
            await db.SaveChangesAsync();
            return Results.Ok();
        });
    }
}
```

